// LnkSearchMachine returns an HRESULT ([MS-DLTW] 3.1.4.1): a value of 0 or any positive
// value indicates success and a negative value indicates failure — use StatusIsSuccess to
// test, since for an HRESULT success is the severity bit and not the single value zero.
// The success value and the common failures are not declared here, because the whole of
// [MS-ERREF] 2.1.1 lives in
// github.com/TheManticoreProject/Manticore/windows/errors/hresult as the HRESULT type;
// convert a returned status with hresult.HRESULT(status) and let the shared table name it.
//
// The three values below stay local, because the shared table names none of them and
// nothing in it may be substituted for them. TRK_E_REFERRAL and TRK_E_POTENTIAL_FILE_FOUND
// come from a private Distributed Link Tracking facility — the 0xDEA that reads as an
// 11-bit facility field of 0x5EA — which [MS-ERREF] 2.1 assigns to nothing and
// [MS-ERREF] 2.1.1 does not cover, and EPT_S_NOT_REGISTERED is the NTSTATUS-shaped RPC
// endpoint-mapper failure of [MS-ERREF] 2.3, which is a third error space again. So
// StatusString decodes these three itself and defers every other value to the shared
// table.
const (
	// TrkEReferral — the file has moved off this server; pmcidNext/pdroidNext refer the
	// client to the server that now holds it ([MS-DLTW] 3.1.4.1). A failure HRESULT that
	// nonetheless carries meaningful [out] parameters, so callers inspect it specifically.
	TrkEReferral uint32 = 0x8DEAD101
	// TrkEPotentialFileFound — a file matching some but not all criteria was found;
	// pdroidBirthNext carries the candidate FileID ([MS-DLTW] 3.1.4.1). Also a failure
	// HRESULT with meaningful [out] parameters.
	TrkEPotentialFileFound uint32 = 0x8DEAD106
	// EptSNotRegistered — the requested endpoint was not found; when it was reached over
	// \trkwks the client retries over \ntsvcs ([MS-DLTW] 3.2.4.1, [MS-RPCE]).
	EptSNotRegistered uint32 = 0xC0020017
)

// StatusIsSuccess reports whether an HRESULT returned by this interface indicates success.
// HRESULTs are signed: success is any value with the sign bit clear (>= 0), matching
// [MS-DLTW] 3.1.4.1 ("a value of 0 or any positive value indicates success"). It defers to
// hresult.HRESULT.IsSuccess rather than testing the bit itself, so the one definition of
// the HRESULT severity rule lives with the table; a caller already holding a
// hresult.HRESULT should call that method directly.
func StatusIsSuccess(status uint32) bool {
	return hresult.HRESULT(status).IsSuccess()
}

