// StatusString names the three statuses that come from error spaces the shared [MS-ERREF]
// 2.1.1 table does not cover, and defers every other status to that table, which names
// each value the specification defines and renders hex only for values it does not.
func StatusString(status uint32) string {
	switch status {
	case TrkEReferral:
		return "TRK_E_REFERRAL"
	case TrkEPotentialFileFound:
		return "TRK_E_POTENTIAL_FILE_FOUND"
	case EptSNotRegistered:
		return "EPT_S_NOT_REGISTERED"
	default:
		return hresult.HRESULT(status).String()
	}
}

